 if(!imported&&baseModel){
  const walk=baseModel.userData.walk;
  if(walk){ // com esqueleto: anima de verdade; parado volta à pose inicial
   walk.timeScale=ritmo;
   // andando: entra a caminhada; parado: a caminhada some aos poucos e o boneco volta à pose em pé
   if(moving&&!baseModel.userData.andando){baseModel.userData.andando=true;walk.reset();walk.paused=false;walk.setEffectiveWeight(1);walk.fadeIn(.2).play()}
   if(!moving&&baseModel.userData.andando){baseModel.userData.andando=false;walk.fadeOut(.3)}
   return;
  }
  // Sem esqueleto: passo com leve balanço.
  baseModel.position.y=moving?Math.abs(Math.sin(t*9))*.06:0;
  baseModel.rotation.z=moving?Math.sin(t*9)*.04:0;
  return;
 }
 if(imported){
  if(mixer&&clips){
   const want=moving?(clips.walk||clips.idle):(clips.idle||clips.walk);
   if(want&&group.userData.current!==want){group.userData.current?.fadeOut(.2);want.reset().fadeIn(.2).play();group.userData.current=want}
  }
  if(!mixer)imported.position.y=moving?Math.abs(Math.sin(t*9))*.08:0;
  return;
 }
 if(!legs)return;
 const {knees,elbows,torso,curva}=group.userData;
 const f=t*8.5*ritmo,sw=moving?Math.sin(f):0;
 legs[0].rotation.x=sw*.55;legs[1].rotation.x=-sw*.55;
 // joelho dobra quando a perna volta
 knees[0].rotation.x=moving?Math.max(0,-Math.sin(f-.9))*.9+.05:0;
 knees[1].rotation.x=moving?Math.max(0,Math.sin(f-.9))*.9+.05:0;
 arms[0].rotation.x=-sw*.5;arms[1].rotation.x=sw*.5;
 elbows[0].rotation.x=-.18-(moving?Math.max(0,sw)*.35:0);elbows[1].rotation.x=-.18-(moving?Math.max(0,-sw)*.35:0);
 torso.rotation.y=sw*.07;torso.rotation.x=curva+(moving?.04:0);
 const breath=Math.sin(t*1.8)*.006;
 rig.position.y=moving?Math.abs(Math.cos(f))*.035:breath;
 torso.scale.set(1+breath*.6,1,1+breath*1.2);
}

// Importa um .glb/.gltf do próprio usuário. Fica só no navegador dele.
export const IMPORT_MAX_BYTES=15*1024*1024;
export async function importModel(group,file){
 if(!file)throw new Error('Nenhum arquivo.');
 if(!/\.(glb|gltf)$/i.test(file.name))throw new Error('Use um arquivo .glb ou .gltf.');
 if(file.size>IMPORT_MAX_BYTES)throw new Error('Arquivo maior que 15 MB.');
