 const faisca=new Particulas(scene,{max:1500,mapa:texRadial([[0,'rgba(255,255,255,1)'],[.4,'rgba(255,230,160,.8)'],[1,'rgba(255,160,40,0)']]),aditivo:true,gravidade:9.8,arrasto:.6,crescer:-.6,esfriar:true});
