 const ajustar=()=>{const h=renderer.domElement.clientHeight||600;for(const p of [fogo,fumaca,faisca,poeira])p.mat.uniforms.escala.value=h/(2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2)))};
