function publicarTeloes() { const pkt = { type: 'teloes', slots: anuncios.publico() }; for (const code of rooms.keys()) broadcast(code, pkt); }

async function confirmarPagamento(ad) {
  if (!ad?.pagamento || ad.status !== 'aguardando_pagamento' || !pagamentos.configurado()) return ad;
  const p = await pagamentos.consultar(ad.pagamento.id);
  if (p.status === 'approved' && p.referencia === ad.id && Math.abs(p.valor - ad.valor) < 0.01) anuncios.marcarPago(ad.id, 'mercadopago');
  return anuncios.buscar(ad.id);
}

async function api(req, res, url) {
  const p = url.pathname, m = req.method;
  if (p === '/api/teloes' && m === 'GET') return json(res, 200, { slots: anuncios.publico(), pagamentoOnline: pagamentos.configurado() });
  if (p === '/api/anuncios' && m === 'POST') {
    const corpo = await lerCorpo(req);
    const ad = anuncios.criar(corpo, ipDe(req));
    let aviso = null;
    if (pagamentos.configurado()) {
      try {
        const cobranca = await pagamentos.criarPix({
          valor: ad.valor, descricao: `Anúncio Ágora Brasil · ${ad.slot} · ${ad.dias} dia(s)`, email: ad.contato, referencia: ad.id,
          notificacao: PUBLIC_URL ? `${PUBLIC_URL}/api/pagamentos/webhook` : null,
        });
        anuncios.registrarCobranca(ad.id, cobranca);
      } catch (e) { aviso = 'Não foi possível gerar o Pix agora. Seu pedido foi salvo; tente consultar de novo em instantes.'; console.error(e.message); }
    } else aviso = 'Pagamento online ainda não está ativo neste servidor. Seu pedido foi salvo e a equipe entra em contato pelo e-mail.';
    return json(res, 201, { ...anuncios.status(anuncios.buscar(ad.id)), chave: ad.chave, aviso });
  }
  const consulta = /^\/api\/anuncios\/([a-f0-9]{16})$/.exec(p);
  if (consulta && m === 'GET') {
    let ad = anuncios.doDono(consulta[1], url.searchParams.get('chave'));
    if (!ad) return json(res, 404, { erro: 'Anúncio não encontrado.' });
    try { ad = await confirmarPagamento(ad); } catch (e) { console.error(e.message); }
    return json(res, 200, anuncios.status(ad));
  }
  if (p === '/api/pagamentos/webhook' && m === 'POST') {
    const corpo = await lerCorpo(req, 64 * 1024).catch(() => ({}));
    const pid = String(corpo?.data?.id || url.searchParams.get('data.id') || url.searchParams.get('id') || '');
    if (pid && pagamentos.configurado()) {
      try {
        const pg = await pagamentos.consultar(pid);
        const ad = anuncios.buscar(pg.referencia);
        if (ad && pg.status === 'approved' && Math.abs(pg.valor - ad.valor) < 0.01) anuncios.marcarPago(ad.id, 'mercadopago');
      } catch (e) { console.error(e.message); }
    }
    return json(res, 200, { ok: true });
  }
  if (p.startsWith('/api/admin/')) {
    if (!ADMIN_TOKEN) return json(res, 503, { erro: 'Defina ADMIN_TOKEN no servidor para usar a moderação.' });
    if (!adminOk(req)) return json(res, 401, { erro: 'Token de administrador inválido.' });
    if (p === '/api/admin/anuncios' && m === 'GET') return json(res, 200, { anuncios: anuncios.admin() });
    const acao = /^\/api\/admin\/anuncios\/([a-f0-9]{16})\/(aprovar|recusar|pago)$/.exec(p);
    if (acao && m === 'POST') {
      const corpo = await lerCorpo(req, 8 * 1024).catch(() => ({}));
      const ad = acao[2] === 'aprovar' ? anuncios.aprovar(acao[1]) : acao[2] === 'recusar' ? anuncios.recusar(acao[1], corpo.motivo) : anuncios.marcarPago(acao[1], 'manual');
      if (acao[2] !== 'pago') publicarTeloes();
      const { chave, ...semChave } = ad;
      return json(res, 200, semChave);
    }
  }
  return json(res, 404, { erro: 'Rota não encontrada.' });
}

const server=http.createServer((req,res)=>{
  let url;
  try { url=new URL(req.url, 'http://localhost'); }
  catch { res.writeHead(400).end('Bad Request'); return; }
  if(url.pathname.startsWith('/api/')) {
    api(req,res,url).catch((e)=>json(res,e.status||500,{erro:e.status?e.message:'Erro interno.'}));
    return;
  }
  const img=/^\/anuncios\/img\/([a-f0-9]{16}\.(png|jpg|webp))$/.exec(url.pathname);
  if(img) {
    const arq=path.join(DATA,'imagens',img[1]);
    fs.stat(arq,(err,st)=>{
      if(err||!st.isFile()){res.writeHead(404).end('Not Found');return;}
      res.writeHead(200,{'content-type':{png:'image/png',jpg:'image/jpeg',webp:'image/webp'}[img[2]],'x-content-type-options':'nosniff','cache-control':'public, max-age=3600'});
      fs.createReadStream(arq).pipe(res);
    });
    return;
  }
  if(url.pathname==='/admin') url.pathname='/admin.html';
  if(url.pathname==='/health') {
    res.writeHead(200,{'content-type':'application/json','cache-control':'no-store'});
    res.end(JSON.stringify({ok:true,rooms:rooms.size,players:[...rooms.values()].reduce((n,s)=>n+s.size,0)}));
    return;
  }
  let pathname;
  try { pathname=decodeURIComponent(url.pathname); }
  catch {res.writeHead(400).end('Bad Request');return;}
  if(pathname==='/'||pathname==='') pathname='/index.html';
  const full=path.resolve(PUBLIC,'.'+pathname);
  if(!full.startsWith(PUBLIC+path.sep) && full!==PUBLIC) {
    res.writeHead(403).end('Forbidden');return;
  }
  fs.stat(full,(err,stat)=>{
    if(err||!stat.isFile()){res.writeHead(404).end('Not Found');return;}
    res.writeHead(200,{
      'content-type': MIME[path.extname(full).toLowerCase()]||'application/octet-stream',
      'x-content-type-options':'nosniff',
      'cache-control':/\.(glb|png|webp)$/.test(full)?'public, max-age=600':'no-cache'
    });
    fs.createReadStream(full).pipe(res);
  });
});
const wss=new WebSocketServer({server,maxPayload:LIMIT_BYTES});
wss.on('connection',(ws)=>{
  ws.playerId='p'+nextId++;
  ws.room=null;ws.name='Visitante';ws.lastChat=0;ws.lastMove=0;setLook(ws,null);
  send(ws,{type:'hello',id:ws.playerId});
  ws.on('message',(raw)=>{
    let msg;try { msg=JSON.parse(String(raw)); }catch{return;}
    if(!msg||typeof msg!=='object') return;
    if(msg.type==='join') {
      leave(ws);
      ws.room=roomCode(msg.room);
      ws.name=clean(msg.name,24)||'Visitante';
      setLook(ws,msg.look||msg);
      if(!rooms.has(ws.room)) rooms.set(ws.room,new Set());
      const occupants=peers(ws.room).map(p=>({
        id:p.playerId,name:p.name,look:p.look,position:p.position||{x:0,z:-30}
      }));
      rooms.get(ws.room).add(ws);
      send(ws,{type:'joined',room:ws.room,peers:occupants,count:peers(ws.room).length});
      broadcast(ws.room,{type:'enter',id:ws.playerId,name:ws.name,look:ws.look,position:ws.position||{x:0,z:-30}},ws);
      publishCount(ws.room);
      send(ws,{type:'debate',state:debateOf(ws.room).estado()});
      send(ws,{type:'teloes',slots:anuncios.publico()});
      combateOf(ws.room).entrar(ws.playerId,ws.team,ws.position||{x:0,z:-30});
      send(ws,{type:'pvp',estado:combateOf(ws.room).estado()});
      return;
    }
    if(!ws.room) return;
    if(msg.type==='look') {
      setLook(ws,msg.look||msg);
      broadcast(ws.room,{type:'look',id:ws.playerId,look:ws.look});
      combateOf(ws.room).trocarTime(ws.playerId,ws.team);
      return;
    }
    if(typeof msg.type==='string'&&msg.type.startsWith('debate-')) {
      const debate=debateOf(ws.room),now=Date.now();
      if(msg.type==='debate-join') debate.entrarFila(player(ws),now);
      if(msg.type==='debate-leave') debate.sairFila(ws.playerId);
      if(msg.type==='debate-say') debate.falar(ws.playerId,clean(msg.text,280),now);
      if(msg.type==='debate-pass') debate.passarVez(ws.playerId,now);
      if(msg.type==='debate-vote') debate.votar(ws.playerId,msg.side);
      return;
    }
    if(typeof msg.type==='string'&&msg.type.startsWith('pvp-')) { pvp(ws,msg); return; }
    if(msg.type==='chat') {
      const now=Date.now();
      if(now-ws.lastChat<1200) return;
      ws.lastChat=now;
      const text=clean(msg.text,180);
      if(text) broadcast(ws.room,{type:'chat',id:ws.playerId,name:ws.name,text,time:now});
    }
    if(msg.type==='move') {
      const now=Date.now();
      if(now-ws.lastMove<70) return;ws.lastMove=now;
      const x=Number(msg.x),z=Number(msg.z);
      if(!Number.isFinite(x)||!Number.isFinite(z)||Math.abs(x)>350||Math.abs(z)>950) return;
      const c=combateOf(ws.room);
      if(!c.mover(ws.playerId,x,z)&&c.jogadores.has(ws.playerId)) return; // morto ou dirigindo
      ws.position={x,z};
      broadcast(ws.room,{type:'move',id:ws.playerId,x,z},ws);
    }
  });
  ws.on('close',()=>leave(ws));
  ws.on('error',()=>leave(ws));
});
// Mensagens do modo PvP. O servidor decide vida, dano, itens e veículos.
const ID = (v) => (typeof v === 'string' ? v.slice(0, 16) : '');
function pvp(ws, msg) {
  const c = combateOf(ws.room), id = ws.playerId, now = Date.now();
  ws.pvpN = (now - (ws.pvpT || 0) > 1000) ? 0 : (ws.pvpN || 0); if (!ws.pvpN) ws.pvpT = now;
  if (++ws.pvpN > 40) return; // no máximo 40 mensagens de combate por segundo
  switch (msg.type) {
    case 'pvp-pegar': c.pegar(id, ID(msg.pickup)); break;
    case 'pvp-largar': c.largar(id); break;
    case 'pvp-entrar': c.entrarVeiculo(id, ID(msg.veiculo)); break;
    case 'pvp-sair': {
      if (c.sairVeiculo(id)) { const j = c.jogadores.get(id); ws.position = { x: j.pos.x, z: j.pos.z }; }
      break;
    }
    case 'pvp-veiculo': {
      if (now - (ws.lastVeh || 0) < 45) return; ws.lastVeh = now;
      const v = c.moverVeiculo(id, msg);
      if (v) { ws.position = { x: v.x, z: v.z }; broadcast(ws.room, { type: 'veiculo-mov', id: v.id, x: v.x, y: v.y, z: v.z, ry: v.ry, rx: v.rx, rz: v.rz, vel: v.vel }, ws); }
      break;
    }
    case 'pvp-disparo': {
      const r = c.disparar(id, ID(msg.arma), { o: msg.o, d: msg.d });
      send(ws, { type: 'pvp-bilhete', ref: Number(msg.ref) || 0, ok: r.ok, tiro: r.tiro, motivo: r.motivo });
      break;
    }
    case 'pvp-acerto': c.acertar(id, ID(msg.tiro), { alvo: msg.alvo, alvoVeiculo: msg.alvoVeiculo, ponto: msg.ponto }); break;
    case 'pvp-ataque': c.atacar(id, ID(msg.arma), { alvo: msg.alvo, alvoVeiculo: msg.alvoVeiculo }); break;
    case 'pvp-golpe-visual': {
      if (now - (ws.lastGolpe || 0) < 300 || !c.vivo(id)) return; ws.lastGolpe = now;
      broadcast(ws.room, { type: 'golpe-visual', de: id, rugido: !!msg.rugido }, ws);
      break;
    }
  }
}
function tickCombates() { for (const c of combates.values()) c.tick(); }
function tickDebates(now=Date.now()) { for(const debate of debates.values()) debate.tick(now); }
if(require.main===module) {
  setInterval(tickDebates,500).unref();
  setInterval(tickCombates,250).unref();
  setInterval(()=>{ if(anuncios.expirar()) publicarTeloes(); },60e3).unref();
  server.listen(PORT,HOST,()=>console.log('Ágora Brasil em http://localhost:'+PORT));
}
module.exports={server,clean,roomCode,team,outfit,lookOf,tickDebates,tickCombates,anuncios,combates};

'use strict';
// Combate PvP: vida, itens, veículos e placar, uma instância por sala.
// Regras do projeto:
// - armas atingem só jogadores e veículos; prédios não têm vida e não sofrem dano;
// - sem fogo amigo; 3 s de proteção ao renascer; a tribuna do debate é zona segura;
// - o cliente simula o tiro e informa o acerto; o servidor valida arma, recarga, alcance, time e
//   que cada tiro só acerta uma vez (bilhete do disparo).

const ARMAS = {
  espada: { dano: 34, alcance: 3.6, recarga: 550, mao: true, corpo: true },
  arco: { dano: 42, alcance: 160, recarga: 850, mao: true },
  bomba: { dano: 90, raio: 7, alcance: 45, recarga: 1200, mao: true, gasta: true },
  metralhadora: { dano: 9, alcance: 220, recarga: 90, veiculo: ['helicoptero'] },
  'missil-heli': { dano: 75, raio: 6, alcance: 500, recarga: 1400, veiculo: ['helicoptero'] },
  'missil-caca': { dano: 95, raio: 8, alcance: 900, recarga: 1700, veiculo: ['caca'] },
  mordida: { dano: 60, alcance: 9, recarga: 1100, veiculo: ['trex'], corpo: true },
  atropelar: { dano: 45, alcance: 7, recarga: 900, veiculo: ['carro', 'moto'], corpo: true },
};
const VEICULOS = {
  carro: { vida: 260 }, moto: { vida: 160 }, helicoptero: { vida: 420 }, caca: { vida: 360 }, trex: { vida: 650 },
};
const VOADORES = new Set(['helicoptero', 'caca']);
const BASES = { vermelho: { x: -70, z: 120 }, amarelo: { x: 70, z: 120 } };
const ZONAS_SEGURAS = [{ x: 42, z: -62, r: 26 }]; // tribuna do debate
const VIDA = 100, RENASCE_MS = 5000, PROTECAO_MS = 3000, ITEM_VOLTA_MS = 20000, VEICULO_VOLTA_MS = 30000, VITORIA = 25;
const MARGEM = 8; // tolerância de rede para posições (m)
const BILHETE_MS = 12000;

// Pontos fixos do mapa (metros, mesmo sistema da cidade.js; gramado central entre x -117 e 117).
const PICKUPS = [
  // Equipamentos visíveis e acessíveis a partir do ponto inicial (0, -30).
  ['espada', -5, -22], ['arco', 0, -19], ['bomba', 5, -22],
  ['espada', -20, 40], ['espada', 20, 40], ['espada', -40, 300], ['espada', 40, 300],
  ['arco', 0, 90], ['arco', -60, 220], ['arco', 60, 220], ['arco', 0, 470],
  ['bomba', -25, 170], ['bomba', 25, 170], ['bomba', -25, 400], ['bomba', 25, 400],
].map(([item, x, z], i) => ({ id: 'i' + i, item, x, z }));
const GARAGEM = [
  // Veículos de teste perto da praça inicial, sem remover as garagens existentes.
  ['moto', -15, -4, 0], ['carro', 15, -4, 0],
  ['trex', 0, 5, Math.PI], ['helicoptero', -37, 12, Math.PI], ['caca', 37, 12, Math.PI],
  ['carro', -124, 60, 0], ['carro', -124, 180, 0], ['carro', 124, 120, Math.PI],
  ['moto', 124, 60, Math.PI], ['moto', 124, 180, Math.PI], ['moto', -124, 120, 0],
  ['helicoptero', -55, 560, Math.PI], ['helicoptero', 55, 560, Math.PI],
  ['caca', -60, 700, Math.PI], ['caca', 60, 700, Math.PI],
  ['trex', 0, 330, Math.PI],
].map(([tipo, x, z, ry], i) => ({ id: 'v' + i, tipo, x, z, ry }));

const d3 = (a, b) => Math.hypot(a.x - b.x, (a.y || 0) - (b.y || 0), a.z - b.z);
const num = (v, min, max) => (v !== null && v !== '' && v !== undefined && Number.isFinite(Number(v)) ? Math.min(max, Math.max(min, Number(v))) : null);
function ponto(p, lim = 3000) {
  if (!p || typeof p !== 'object') return null;
  const x = num(p.x, -lim, lim), y = num(p.y, -lim, lim), z = num(p.z, -lim, lim);
  return x === null || y === null || z === null ? null : { x, y, z };
}
const naZonaSegura = (p) => ZONAS_SEGURAS.some((z) => Math.hypot(p.x - z.x, p.z - z.z) < z.r);

class Combate {
  constructor({ emit = () => {}, agora = () => Date.now() } = {}) {
    this.emit = emit; this.agora = agora;
    this.jogadores = new Map();
    this.placar = { vermelho: 0, amarelo: 0 };
    this.vencedor = null; this.reinicioEm = 0;
    this.pickups = PICKUPS.map((p) => ({ ...p, disponivel: true, voltaEm: 0 }));
    this.veiculos = GARAGEM.map((g) => this.novoVeiculo(g));
    this.tiros = new Map(); this.nTiro = 0;
  }

  novoVeiculo(g) {
    return { id: g.id, tipo: g.tipo, spawn: g, x: g.x, y: 0, z: g.z, ry: g.ry, rx: 0, rz: 0, vel: 0, vida: VEICULOS[g.tipo].vida, motorista: null, destruidoEm: 0 };
  }
  veiculo(id) { return this.veiculos.find((v) => v.id === id) || null; }
  posDe(j) {
    if (j.veiculo) { const v = this.veiculo(j.veiculo); if (v) return v; }
    return j.pos;
  }
  pub(j) { return { id: j.id, team: j.team, vida: j.vida, vivo: j.vivo, item: j.item, veiculo: j.veiculo }; }
  pubV(v) { return { id: v.id, tipo: v.tipo, x: v.x, y: v.y, z: v.z, ry: v.ry, rx: v.rx, rz: v.rz, vida: v.vida, max: VEICULOS[v.tipo].vida, motorista: v.motorista, ativo: !v.destruidoEm }; }

  estado() {
    return {
      jogadores: [...this.jogadores.values()].map((j) => this.pub(j)),
      veiculos: this.veiculos.map((v) => this.pubV(v)),
      pickups: this.pickups.map((p) => ({ id: p.id, item: p.item, x: p.x, z: p.z, disponivel: p.disponivel })),
      placar: { ...this.placar }, vencedor: this.vencedor, bases: BASES, zonas: ZONAS_SEGURAS, vitoria: VITORIA,
    };
  }

  entrar(id, team, pos) {
    const j = { id, team: team === 'amarelo' ? 'amarelo' : 'vermelho', vida: VIDA, vivo: true, item: null, veiculo: null,
      pos: { x: pos?.x ?? 0, y: 0, z: pos?.z ?? 0 }, protegidoAte: this.agora() + PROTECAO_MS, mortoEm: 0, ultimo: {} };
    this.jogadores.set(id, j);
    this.emit({ type: 'jogador', jogador: this.pub(j) });
    return j;
  }
  trocarTime(id, team) {
    const j = this.jogadores.get(id); if (!j) return;
    j.team = team === 'amarelo' ? 'amarelo' : 'vermelho';
    this.emit({ type: 'jogador', jogador: this.pub(j) });
  }
  sair(id) {
    if (!this.jogadores.has(id)) return;
    this.sairVeiculo(id);
    this.jogadores.delete(id);
  }
  vivo(id) { const j = this.jogadores.get(id); return !!j && j.vivo; }

  mover(id, x, z) {
    const j = this.jogadores.get(id); if (!j || !j.vivo || j.veiculo) return false;
    j.pos = { x, y: 0, z };
    return true;
  }

  pegar(id, pickupId) {
    const j = this.jogadores.get(id), p = this.pickups.find((q) => q.id === pickupId);
    if (!j || !p || !j.vivo || j.veiculo || !p.disponivel) return false;
    if (Math.hypot(j.pos.x - p.x, j.pos.z - p.z) > 3.5 + MARGEM) return false;
    j.item = p.item; p.disponivel = false; p.voltaEm = this.agora() + ITEM_VOLTA_MS;
    this.emit({ type: 'pickup', id: p.id, disponivel: false });
    this.emit({ type: 'jogador', jogador: this.pub(j) });
    return true;
  }
  largar(id) {
    const j = this.jogadores.get(id);
    if (j && j.item) { j.item = null; this.emit({ type: 'jogador', jogador: this.pub(j) }); }
  }

  entrarVeiculo(id, vid) {
    const j = this.jogadores.get(id), v = this.veiculo(vid);
    if (!j || !v || !j.vivo || j.veiculo || v.motorista || v.destruidoEm) return false;
    if (Math.hypot(j.pos.x - v.x, j.pos.z - v.z) > 10 + MARGEM) return false;
    v.motorista = id; j.veiculo = vid;
    this.emit({ type: 'veiculo', veiculo: this.pubV(v) });
    this.emit({ type: 'jogador', jogador: this.pub(j) });
    return true;
  }
  sairVeiculo(id) {
    const j = this.jogadores.get(id); if (!j || !j.veiculo) return false;
    const v = this.veiculo(j.veiculo); j.veiculo = null;
    if (v) {
      v.motorista = null; v.vel = 0;
      j.pos = { x: v.x + Math.cos(v.ry) * 3, y: 0, z: v.z - Math.sin(v.ry) * 3 };
      if (v.y > 0.5) { v.y = 0; v.rx = 0; v.rz = 0; } // aeronave abandonada pousa onde está
      this.emit({ type: 'veiculo', veiculo: this.pubV(v) });
    }
    this.emit({ type: 'jogador', jogador: this.pub(j), pos: j.pos });
    return true;
  }
  moverVeiculo(id, s) {
    const j = this.jogadores.get(id); if (!j || !j.veiculo || !s) return null;
    const v = this.veiculo(j.veiculo); if (!v || v.motorista !== id) return null;
    const x = num(s.x, -2500, 2500), z = num(s.z, -2500, 2500), y = num(s.y, 0, 600);
    if (x === null || z === null || y === null) return null;
    v.x = x; v.z = z; v.y = VOADORES.has(v.tipo) ? y : 0;
    v.ry = num(s.ry, -1000, 1000) ?? v.ry; v.rx = num(s.rx, -3.2, 3.2) ?? 0; v.rz = num(s.rz, -3.2, 3.2) ?? 0;
    v.vel = num(s.vel, -200, 200) ?? 0;
    return v;
  }

  // 1º passo de todo ataque: valida e devolve um bilhete. O efeito visual vai para a sala.
  disparar(id, arma, vis = {}) {
    const agora = this.agora(), j = this.jogadores.get(id), a = ARMAS[arma];
    if (!j || !j.vivo || !a) return { ok: false, motivo: 'indisponivel' };
    if (this.vencedor) return { ok: false, motivo: 'fim-de-partida' };
    if (a.mao && (j.item !== arma || j.veiculo)) return { ok: false, motivo: 'sem-item' };
    if (a.veiculo) { const v = j.veiculo && this.veiculo(j.veiculo); if (!v || !a.veiculo.includes(v.tipo)) return { ok: false, motivo: 'sem-veiculo' }; }
    if (agora - (j.ultimo[arma] || 0) < a.recarga * 0.8) return { ok: false, motivo: 'recarga' };
    j.ultimo[arma] = agora;
    if (a.gasta) { j.item = null; this.emit({ type: 'jogador', jogador: this.pub(j) }); }
    const origem = { ...this.posDe(j) };
    const tiro = 't' + (++this.nTiro);
    this.tiros.set(tiro, { autor: id, arma, origem, em: agora, usado: false });
    if (this.tiros.size > 400) for (const [k, t] of this.tiros) if (agora - t.em > BILHETE_MS) this.tiros.delete(k);
    if (!a.corpo) {
      const o = ponto(vis.o), d = ponto(vis.d, 2);
      this.emit({ type: 'disparo', de: id, arma, tiro, o: o || origem, d: d || { x: 0, y: 0, z: 1 } });
    } else this.emit({ type: 'golpe', de: id, arma });
    return { ok: true, tiro };
  }

  // 2º passo: o cliente informa o que o tiro atingiu (um jogador, um veículo ou o ponto da explosão).
  acertar(id, tiroId, alvo = {}) {
    const agora = this.agora(), t = this.tiros.get(tiroId), j = this.jogadores.get(id);
    if (!t || t.autor !== id || t.usado || agora - t.em > BILHETE_MS || !j) return { ok: false, motivo: 'bilhete' };
    t.usado = true;
    const a = ARMAS[t.arma], eventos = [];
    if (a.raio) {
      const p = ponto(alvo.ponto);
      if (!p || d3(t.origem, p) > a.alcance + MARGEM * 2) return { ok: false, motivo: 'alcance' };
      this.emit({ type: 'explosao', arma: t.arma, de: id, x: p.x, y: p.y, z: p.z, raio: a.raio });
      for (const alvoJ of this.jogadores.values()) {
        if (alvoJ.team === j.team || !alvoJ.vivo) continue;
        const dist = d3(this.posDe(alvoJ), p);
        if (dist <= a.raio + 1) eventos.push(...this.ferir(alvoJ, Math.round(a.dano * (1 - 0.6 * Math.min(1, dist / a.raio))), j, t.arma));
      }
      for (const v of this.veiculos) {
        if (v.destruidoEm || v.id === j.veiculo || this.mesmoTime(v, j)) continue;
        const dist = d3(v, p);
        if (dist <= a.raio + 3) eventos.push(...this.ferirVeiculo(v, Math.round(a.dano * 1.2 * (1 - 0.5 * Math.min(1, dist / (a.raio + 3)))), j, t.arma));
      }
      return { ok: true, eventos };
    }
    const folga = a.corpo ? MARGEM : MARGEM * 2;
    if (typeof alvo.alvo === 'string') {
      const alvoJ = this.jogadores.get(alvo.alvo);
      if (!alvoJ || !alvoJ.vivo || alvoJ.team === j.team) return { ok: true, eventos };
      if (d3(a.corpo ? this.posDe(j) : t.origem, this.posDe(alvoJ)) > a.alcance + folga) return { ok: false, motivo: 'alcance' };
      eventos.push(...this.ferir(alvoJ, a.dano, j, t.arma));
    } else if (typeof alvo.alvoVeiculo === 'string') {
      const v = this.veiculo(alvo.alvoVeiculo);
      if (!v || v.destruidoEm || v.id === j.veiculo || this.mesmoTime(v, j)) return { ok: true, eventos };
      if (d3(a.corpo ? this.posDe(j) : t.origem, v) > a.alcance + folga + 5) return { ok: false, motivo: 'alcance' };
      eventos.push(...this.ferirVeiculo(v, a.dano, j, t.arma));
    }
    return { ok: true, eventos };
  }

  // Golpe corpo a corpo (espada, mordida, atropelar): disparo e acerto juntos.
  atacar(id, arma, alvo) {
    const r = this.disparar(id, arma);
    return r.ok ? this.acertar(id, r.tiro, alvo) : r;
  }

  mesmoTime(v, j) { const m = v.motorista && this.jogadores.get(v.motorista); return !!m && m.team === j.team; }

  ferir(alvo, dano, autor, arma) {
    if (this.agora() < alvo.protegidoAte || dano <= 0 || !alvo.vivo) return [];
    if (!alvo.veiculo && naZonaSegura(alvo.pos)) return [];
    alvo.vida = Math.max(0, alvo.vida - dano);
    const ev = { type: 'dano', alvo: alvo.id, vida: alvo.vida, de: autor.id, arma };
    this.emit(ev);
    return alvo.vida === 0 ? [ev, ...this.matar(alvo, autor, arma)] : [ev];
  }

  ferirVeiculo(v, dano, autor, arma) {
    if (dano <= 0) return [];
    v.vida = Math.max(0, v.vida - dano);
    const ev = [{ type: 'dano-veiculo', veiculo: v.id, vida: v.vida, de: autor.id, arma }];
    this.emit(ev[0]);
    if (v.vida === 0) {
      v.destruidoEm = this.agora();
      const motorista = v.motorista && this.jogadores.get(v.motorista);
      const e = { type: 'explosao-veiculo', veiculo: v.id, x: v.x, y: v.y, z: v.z };
      if (motorista) this.sairVeiculo(motorista.id);
      v.motorista = null;
      this.emit(e); ev.push(e);
      this.emit({ type: 'veiculo', veiculo: this.pubV(v) });
      if (motorista) { motorista.protegidoAte = 0; ev.push(...this.ferir(motorista, 70, autor, arma)); }
    }
    return ev;
  }

  matar(alvo, autor, arma) {
    alvo.vivo = false; alvo.mortoEm = this.agora(); alvo.item = null;
    if (alvo.veiculo) this.sairVeiculo(alvo.id);
    const ev = [{ type: 'morte', alvo: alvo.id, de: autor.id, arma }];
    this.emit(ev[0]);
    if (autor.team !== alvo.team && !this.vencedor) {
      this.placar[autor.team]++;
      this.emit({ type: 'placar', placar: { ...this.placar } });
      if (this.placar[autor.team] >= VITORIA) {
        this.vencedor = autor.team; this.reinicioEm = this.agora() + 12000;
        this.emit({ type: 'vitoria', time: autor.team, placar: { ...this.placar } });
      }
    }
    return ev;
  }

  tick() {
    const agora = this.agora();
    for (const j of this.jogadores.values()) {
      if (!j.vivo && agora - j.mortoEm >= RENASCE_MS) {
        const b = BASES[j.team];
        j.vivo = true; j.vida = VIDA; j.protegidoAte = agora + PROTECAO_MS;
        j.pos = { x: b.x + (Math.random() - 0.5) * 10, y: 0, z: b.z + (Math.random() - 0.5) * 10 };
        this.emit({ type: 'renasceu', id: j.id, pos: j.pos, vida: j.vida });
      }
    }
    for (const p of this.pickups) if (!p.disponivel && agora >= p.voltaEm) { p.disponivel = true; this.emit({ type: 'pickup', id: p.id, disponivel: true }); }
    for (let i = 0; i < this.veiculos.length; i++) {
      const v = this.veiculos[i];
      if (v.destruidoEm && agora - v.destruidoEm >= VEICULO_VOLTA_MS) {
        this.veiculos[i] = this.novoVeiculo(v.spawn);
        this.emit({ type: 'veiculo', veiculo: this.pubV(this.veiculos[i]) });
      }
    }
    if (this.vencedor && agora >= this.reinicioEm) {
      this.vencedor = null; this.placar = { vermelho: 0, amarelo: 0 };
      this.emit({ type: 'placar', placar: { ...this.placar }, novaPartida: true });
    }
  }
}

module.exports = { Combate, ARMAS, VEICULOS, BASES, PICKUPS, GARAGEM, VITORIA, ZONAS_SEGURAS };

'use strict';
// Modo debate: dois jogadores na tribuna, turnos cronometrados e votação da plateia.
// Máquina de estados pura; o servidor chama tick(now) periodicamente.

const ROTEIRO = [
  { fase: 'abertura', lado: 'a', segundos: 60 },
  { fase: 'abertura', lado: 'b', segundos: 60 },
  { fase: 'replica', lado: 'a', segundos: 45 },
  { fase: 'replica', lado: 'b', segundos: 45 },
  { fase: 'treplica', lado: 'a', segundos: 30 },
  { fase: 'treplica', lado: 'b', segundos: 30 },
  { fase: 'votacao', lado: null, segundos: 30 },
  { fase: 'resultado', lado: null, segundos: 10 },
];
const FALA_MAX = 280;
const FALA_INTERVALO_MS = 2000;

function resumo(p) {
  return p ? { id: p.id, name: p.name, team: p.team } : null;
}

class Debate {
  constructor({ emit, roteiro = ROTEIRO } = {}) {
    this.emit = emit || (() => {});
    this.roteiro = roteiro;
    this.fila = [];
    this.reset();
  }

  reset() {
    this.a = null; this.b = null;
    this.etapa = -1; this.terminaEm = 0;
    this.votos = new Map();
    this.vencedor = null; this.motivo = null;
    this.ultimaFala = new Map();
  }

  get ativo() { return this.etapa >= 0; }
  get passo() { return this.ativo ? this.roteiro[this.etapa] : null; }

  estado() {
    const passo = this.passo;
    const contagem = { a: 0, b: 0 };
    for (const lado of this.votos.values()) contagem[lado]++;
    const mostrarVotos = passo?.fase === 'resultado';
    return {
      fase: passo ? passo.fase : 'aguardando',
      orador: passo?.lado || null,
      a: resumo(this.a), b: resumo(this.b),
      terminaEm: this.terminaEm,
      fila: this.fila.map(resumo),
      votosTotal: this.votos.size,
      votos: mostrarVotos ? contagem : null,
      vencedor: mostrarVotos ? this.vencedor : null,
      motivo: mostrarVotos ? this.motivo : null,
    };
  }

  publicar() { this.emit({ type: 'debate', state: this.estado() }); }

  entrarFila(jogador, now) {
    if (this.fila.some(p => p.id === jogador.id)) return false;
    if (this.a?.id === jogador.id || this.b?.id === jogador.id) return false;
    this.fila.push(jogador);
    this.tentarIniciar(now);
    this.publicar();
    return true;
  }

  sairFila(id) {
    const antes = this.fila.length;
    this.fila = this.fila.filter(p => p.id !== id);
    if (this.fila.length !== antes) this.publicar();
  }

  tentarIniciar(now) {
    if (this.ativo || this.fila.length < 2) return false;
    const a = this.fila.shift();
    // Prefere adversário do outro time; se não houver, pega o próximo da fila.
    let idx = this.fila.findIndex(p => p.team && p.team !== a.team);
    if (idx < 0) idx = 0;
    const b = this.fila.splice(idx, 1)[0];
    this.reset();
    this.a = a; this.b = b;
    this.irPara(0, now);
    return true;
  }

  irPara(etapa, now) {
    this.etapa = etapa;
    this.terminaEm = now + this.roteiro[etapa].segundos * 1000;
    if (this.roteiro[etapa].fase === 'resultado' && !this.vencedor) this.apurar();
    this.publicar();
  }

  apurar() {
    let a = 0, b = 0;
    for (const lado of this.votos.values()) lado === 'a' ? a++ : b++;
    this.vencedor = a === b ? 'empate' : (a > b ? 'a' : 'b');
    this.motivo = 'votacao';
  }

  tick(now) {
    if (!this.ativo) return;
    if (now < this.terminaEm) return;
    const proxima = this.etapa + 1;
    if (proxima < this.roteiro.length) { this.irPara(proxima, now); return; }
    this.reset();
    if (!this.tentarIniciar(now)) this.publicar();
  }

  // Avança o turno atual antes do tempo (o orador passa a vez).
  passarVez(id, now) {
    const passo = this.passo;
    if (!passo?.lado || this[passo.lado].id !== id) return false;
    this.terminaEm = now;
    this.tick(now);
    return true;
  }

  falar(id, texto, now) {
    const passo = this.passo;
    if (!passo?.lado) return null;
    const orador = this[passo.lado];
    if (orador.id !== id) return null;
    if (this.ultimaFala.has(id) && now - this.ultimaFala.get(id) < FALA_INTERVALO_MS) return null;
    const text = String(texto || '').slice(0, FALA_MAX);
    if (!text) return null;
    this.ultimaFala.set(id, now);
    const pacote = { type: 'debate-fala', side: passo.lado, name: orador.name, team: orador.team, text, time: now };
    this.emit(pacote);
    return pacote;
  }

  votar(id, lado) {
    if (this.passo?.fase !== 'votacao') return false;
    if (lado !== 'a' && lado !== 'b') return false;
    if (id === this.a.id || id === this.b.id) return false;
    if (this.votos.has(id)) return false;
    this.votos.set(id, lado);
    this.publicar();
    return true;
  }

  // Jogador saiu da sala: tira da fila; se estava debatendo, o outro vence por W.O.
  saiu(id, now) {
    this.sairFila(id);
    if (!this.ativo) return;
    const lado = this.a.id === id ? 'a' : (this.b.id === id ? 'b' : null);
    if (!lado) { this.votos.delete(id); return; }
    if (this.passo.fase === 'resultado') return;
    this.vencedor = lado === 'a' ? 'b' : 'a';
    this.motivo = 'wo';
    this.irPara(this.roteiro.length - 1, now);
  }
}

module.exports = { Debate, ROTEIRO };

'use strict';
// Telões de anúncio pago: cadastro, pagamento, moderação e rodízio.
// Fluxo: aguardando_pagamento → em_moderacao → no_ar → encerrado (ou recusado).
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');

const SLOTS = [
  { id: 'telao-congresso-norte', nome: 'Telão do Congresso (norte)', local: 'Gramado em frente ao Congresso, lado do Senado', precoDia: 79.9 },
  { id: 'telao-congresso-sul', nome: 'Telão do Congresso (sul)', local: 'Gramado em frente ao Congresso, lado da Câmara', precoDia: 79.9 },
  { id: 'telao-eixo-norte', nome: 'Painel do Eixo (norte)', local: 'Borda do gramado, pista N1', precoDia: 49.9 },
  { id: 'telao-eixo-sul', nome: 'Painel do Eixo (sul)', local: 'Borda do gramado, pista S1', precoDia: 49.9 },
  { id: 'telao-ministerios-norte', nome: 'Painel dos Ministérios (norte)', local: 'Gramado, altura dos ministérios', precoDia: 39.9 },
  { id: 'telao-ministerios-sul', nome: 'Painel dos Ministérios (sul)', local: 'Gramado, altura dos ministérios', precoDia: 39.9 },
  { id: 'telao-praca', nome: 'Telão da Praça dos Três Poderes', local: 'Entrada da Praça dos Três Poderes', precoDia: 59.9 },
];
const DIAS_MAX = 30;
const IMG_MAX_BYTES = 400 * 1024;
const POR_IP_HORA = 5;

// Propaganda político-eleitoral não é aceita (regra do projeto + legislação eleitoral). A moderação manual é a palavra final.
const BLOQUEADOS = [
  /\bvot(e|o|os|ar|em|ando|ação|acao)\b/, /elei[çc](ão|ao|ões|oes)/, /candidat/, /\bpartido/, /\burna/, /\btse\b/,
  /\blula\b/, /bolsonaro/, /fl[áa]vio\b/, /\bpt\b/, /\bpl\b/, /deputad/, /senador/, /governador/, /prefeit/, /vereador/,
  /presidente da rep/, /segundo turno/, /primeiro turno/, /campanha eleitoral/,
];
function normalizar(t) { return String(t || '').toLowerCase(); }
function politico(...textos) { const t = textos.map(normalizar).join(' '); return BLOQUEADOS.some((re) => re.test(t)); }
function limpar(t, max) { return String(t ?? '').replace(/[\u0000-\u001f\u007f<>]/g, '').trim().slice(0, max); }
const HEX = /^#[0-9a-f]{6}$/i;
const EMAIL = /^[^\s@]{1,64}@[^\s@]{1,190}\.[a-z]{2,24}$/i;
const centavos = (v) => Math.round(v * 100) / 100;

function decodeImagem(dataUrl) {
  if (!dataUrl) return null;
  const m = /^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/=]+)$/.exec(String(dataUrl));
  if (!m) throw new Erro('Imagem inválida. Use PNG, JPG ou WEBP.');
  const buf = Buffer.from(m[2], 'base64');
  if (buf.length > IMG_MAX_BYTES) throw new Erro('Imagem maior que 400 KB.');
  const png = buf.slice(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
  const jpg = buf[0] === 0xff && buf[1] === 0xd8;
  const webp = buf.slice(0, 4).toString() === 'RIFF' && buf.slice(8, 12).toString() === 'WEBP';
  const ext = png ? 'png' : jpg ? 'jpg' : webp ? 'webp' : null;
  if (!ext) throw new Erro('O arquivo não é uma imagem válida.');
  return { buf, ext };
}

class Erro extends Error { constructor(msg, status = 400) { super(msg); this.status = status; } }

class Anuncios {
  constructor({ arquivo = null, pastaImagens = null, agora = () => Date.now() } = {}) {
    this.arquivo = arquivo; this.pasta = pastaImagens; this.agora = agora;
    this.lista = []; this.porIp = new Map();
    if (arquivo && fs.existsSync(arquivo)) {
      try { this.lista = JSON.parse(fs.readFileSync(arquivo, 'utf8')); } catch { this.lista = []; }
    }
    if (this.pasta) fs.mkdirSync(this.pasta, { recursive: true });
  }

  salvar() {
    if (!this.arquivo) return;
    fs.mkdirSync(path.dirname(this.arquivo), { recursive: true });
    const tmp = this.arquivo + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(this.lista, null, 1));
    fs.renameSync(tmp, this.arquivo);
  }

  slots() { return SLOTS; }

  criar(input, ip = 'local') {
    const agora = this.agora();
    const janela = (this.porIp.get(ip) || []).filter((t) => agora - t < 3600e3);
    if (janela.length >= POR_IP_HORA) throw new Erro('Muitos pedidos. Tente de novo em uma hora.', 429);
    const slot = SLOTS.find((s) => s.id === input?.slot);
    if (!slot) throw new Erro('Escolha um telão válido.');
    const dias = Math.floor(Number(input.dias));
    if (!(dias >= 1 && dias <= DIAS_MAX)) throw new Erro(`Escolha de 1 a ${DIAS_MAX} dias.`);
    const titulo = limpar(input.titulo, 40), texto = limpar(input.texto, 90);
    if (!titulo) throw new Erro('Escreva um título.');
    const contato = limpar(input.contato, 254);
    if (!EMAIL.test(contato)) throw new Erro('Informe um e-mail válido para o recibo.');
    if (politico(titulo, texto)) throw new Erro('Anúncio político-eleitoral não é aceito nos telões.');
    const cor = HEX.test(input.cor || '') ? input.cor.toLowerCase() : '#0e2a3a';
    const img = decodeImagem(input.imagem);
    const id = crypto.randomBytes(8).toString('hex');
    const chave = crypto.randomBytes(12).toString('hex');
    let imagem = null;
    if (img && this.pasta) { imagem = `${id}.${img.ext}`; fs.writeFileSync(path.join(this.pasta, imagem), img.buf); }
    const ad = {
      id, chave, slot: slot.id, dias, titulo, texto, cor, imagem, contato,
      valor: centavos(slot.precoDia * dias), status: 'aguardando_pagamento', criadoEm: agora,
      pagamento: null, inicio: null, fim: null, motivo: null,
    };
    this.lista.push(ad); janela.push(agora); this.porIp.set(ip, janela); this.salvar();
    return ad;
  }

  buscar(id) { return this.lista.find((a) => a.id === id) || null; }
  doDono(id, chave) {
    const a = this.buscar(id);
    if (!a || !chave || a.chave.length !== String(chave).length) return null;
    return crypto.timingSafeEqual(Buffer.from(a.chave), Buffer.from(String(chave))) ? a : null;
  }

  registrarCobranca(id, pagamento) { const a = this.buscar(id); if (a) { a.pagamento = pagamento; this.salvar(); } return a; }

  marcarPago(id, origem = 'manual') {
    const a = this.buscar(id);
    if (!a) throw new Erro('Anúncio não encontrado.', 404);
    if (a.status !== 'aguardando_pagamento') return a;
    a.status = 'em_moderacao'; a.pagoEm = this.agora(); a.pagoPor = origem; this.salvar();
    return a;
  }

  aprovar(id) {
    const a = this.buscar(id);
    if (!a) throw new Erro('Anúncio não encontrado.', 404);
    if (a.status !== 'em_moderacao') throw new Erro('Só anúncios pagos e em moderação podem ser aprovados.', 409);
    const agora = this.agora();
    a.status = 'no_ar'; a.inicio = agora; a.fim = agora + a.dias * 86400e3; this.salvar();
    return a;
  }

  recusar(id, motivo) {
    const a = this.buscar(id);
    if (!a) throw new Erro('Anúncio não encontrado.', 404);
    if (a.status === 'encerrado' || a.status === 'recusado') return a;
    a.status = 'recusado'; a.motivo = limpar(motivo, 200) || 'Fora das regras dos telões.'; this.salvar();
    return a;
  }

  // Encerra os que venceram. Retorna true se algo mudou.
  expirar() {
    const agora = this.agora(); let mudou = false;
    for (const a of this.lista) if (a.status === 'no_ar' && a.fim <= agora) { a.status = 'encerrado'; mudou = true; }
    if (mudou) this.salvar();
    return mudou;
  }

  // O que os jogadores veem: telões com preço e anúncios no ar (sem e-mail nem chave).
  publico() {
    const agora = this.agora();
    return SLOTS.map((s) => ({
      id: s.id, nome: s.nome, local: s.local, precoDia: s.precoDia,
      anuncios: this.lista
        .filter((a) => a.slot === s.id && a.status === 'no_ar' && a.fim > agora)
        .map((a) => ({ id: a.id, titulo: a.titulo, texto: a.texto, cor: a.cor, imagem: a.imagem ? `/anuncios/img/${a.imagem}` : null })),
    }));
  }

  // Visão do dono do anúncio.
  status(a) {
    return {
      id: a.id, slot: a.slot, dias: a.dias, valor: a.valor, status: a.status, motivo: a.motivo, inicio: a.inicio, fim: a.fim,
      pix: a.pagamento && a.status === 'aguardando_pagamento' ? { copiaECola: a.pagamento.qr, qrBase64: a.pagamento.qrBase64, link: a.pagamento.ticket } : null,
    };
  }

  admin() { return this.lista.map(({ chave, ...resto }) => resto).sort((x, y) => y.criadoEm - x.criadoEm); }
}

module.exports = { Anuncios, SLOTS, Erro, politico, decodeImagem, DIAS_MAX };

'use strict';
// Pix via Mercado Pago (API de pagamentos v1). Só funciona com MP_ACCESS_TOKEN configurado.
// Sem token, o servidor aceita o pedido e o pagamento é confirmado à mão pelo painel /admin.
const crypto = require('node:crypto');

const API = 'https://api.mercadopago.com/v1/payments';

function configurado() { return Boolean(process.env.MP_ACCESS_TOKEN); }

async function criarPix({ valor, descricao, email, referencia, notificacao }) {
  const corpo = {
    transaction_amount: Number(valor.toFixed(2)),
    description: descricao.slice(0, 120),
    payment_method_id: 'pix',
    payer: { email },
    external_reference: referencia,
  };
  if (notificacao) corpo.notification_url = notificacao;
  const r = await fetch(API, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${process.env.MP_ACCESS_TOKEN}`,
      'Content-Type': 'application/json',
      'X-Idempotency-Key': crypto.createHash('sha256').update('pix:' + referencia).digest('hex'),
    },
    body: JSON.stringify(corpo),
  });
  const json = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(`Mercado Pago recusou a cobrança (${r.status}): ${json.message || 'erro'}`);
  const td = json.point_of_interaction?.transaction_data || {};
  return { provedor: 'mercadopago', id: String(json.id), status: json.status, qr: td.qr_code || null, qrBase64: td.qr_code_base64 || null, ticket: td.ticket_url || null };
}

async function consultar(id) {
  const r = await fetch(`${API}/${encodeURIComponent(id)}`, { headers: { Authorization: `Bearer ${process.env.MP_ACCESS_TOKEN}` } });
  if (!r.ok) throw new Error(`Falha ao consultar pagamento (${r.status})`);
  const json = await r.json();
  return { id: String(json.id), status: json.status, referencia: json.external_reference, valor: json.transaction_amount };
}

module.exports = { configurado, criarPix, consultar };

